// Original C# reading examples; addresses are documentation-only.
var loopback = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 7000);
var selected = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Parse("192.0.2.20"), 7000);
var allV4 = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Any, 7000);
