using var client = new System.Net.Sockets.TcpClient();
string host = "localhost";
int servicePort = 7000;
Console.WriteLine($"conn=C12 stage=connect target={host}:{servicePort}");
try {
    await client.ConnectAsync(host, servicePort);
    Console.WriteLine($"conn=C12 stage=connected local={client.Client.LocalEndPoint} remote={client.Client.RemoteEndPoint}");
} catch (System.Net.Sockets.SocketException e) {
    Console.WriteLine($"conn=C12 stage=connect-failed error={e.SocketErrorCode}");
}
